package dev.raven.backup;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class SeekableZipTest {
 interface Check{void run()throws Exception;}
 static void require(boolean v,String m){if(!v)throw new AssertionError(m);}
 static void reject(Check c)throws Exception{try{c.run();}catch(Exception expected){return;}throw new AssertionError("Invalid ZIP accepted");}
 static void put(ByteArrayOutputStream out,long n,int width){for(int i=0;i<width;i++)out.write((int)(n>>>(8*i))&255);}
 static byte[] build(boolean stored)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream out=new ZipOutputStream(bytes)){out.setComment("Comment with PK signature");for(String name:new String[]{"manifest.json","app0-ce.tar","newline\n雪"}){byte[] payload=(name+" contents").getBytes("UTF-8");ZipEntry e=new ZipEntry(name);if(stored){CRC32 crc=new CRC32();crc.update(payload);e.setMethod(0);e.setSize(payload.length);e.setCrc(crc.getValue());}out.putNextEntry(e);out.write(payload);out.closeEntry();}}return bytes.toByteArray();}
 static void check(Path path)throws Exception{try(SeekableZip zip=new SeekableZip(FileChannel.open(path))){Enumeration<ZipEntry> entries=zip.entries();int count=0;while(entries.hasMoreElements()){ZipEntry entry=entries.nextElement();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=zip.getInputStream(entry)){byte[] buf=new byte[31];int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);}CRC32 crc=new CRC32();crc.update(bytes.toByteArray());require(crc.getValue()==entry.getCrc()&&bytes.toString("UTF-8").equals(entry.getName()+" contents"),"ZIP data or CRC");count++;}require(count==3,"entry count");}}
 public static void main(String[] args)throws Exception{Path path=Paths.get("work/seek.zip");for(boolean stored:new boolean[]{false,true}){Files.write(path,build(stored));check(path);}byte[] original=build(false);Files.write(path,original);check(path);int eocd=-1;for(int i=original.length-22;i>=0;i--)if(SeekableZip.u32(original,i)==0x06054b50L){eocd=i;break;}require(eocd>0,"end record");
 // Force ZIP64 end records on a small archive, with the same directory and payloads.
 ByteArrayOutputStream forced=new ByteArrayOutputStream();forced.write(original,0,eocd);put(forced,0x06064b50,4);put(forced,44,8);put(forced,45,2);put(forced,45,2);put(forced,0,4);put(forced,0,4);put(forced,3,8);put(forced,3,8);put(forced,SeekableZip.u32(original,eocd+12),8);put(forced,SeekableZip.u32(original,eocd+16),8);put(forced,0x07064b50,4);put(forced,0,4);put(forced,eocd,8);put(forced,1,4);byte[] end=Arrays.copyOfRange(original,eocd,original.length);Arrays.fill(end,8,20,(byte)255);forced.write(end);Files.write(path,forced.toByteArray());check(path);
 for(int at:new int[]{0,6,8,26,eocd+4,eocd+10,eocd+16}){byte[] bad=original.clone();bad[at]^=1;Files.write(path,bad);reject(()->{try(SeekableZip zip=new SeekableZip(FileChannel.open(path))) {}});}Files.write(path,Arrays.copyOf(original,original.length-1));reject(()->new SeekableZip(FileChannel.open(path)));
 byte[] data=build(false);Path encrypted=Paths.get("work/seek.rbk");char[] password="seekable-password".toCharArray();try(OutputStream out=BackupCrypto.encrypt(Files.newOutputStream(encrypted),password)){out.write(data);}try(BackupCrypto.Reader reader=new BackupCrypto.Reader(FileChannel.open(encrypted),password)){SeekableByteChannel channel=new SeekableByteChannel(){long position;public int read(ByteBuffer b)throws IOException{int n=reader.read(position,b);if(n>0)position+=n;return n;}public int write(ByteBuffer b){throw new UnsupportedOperationException();}public long position(){return position;}public SeekableByteChannel position(long p){position=p;return this;}public long size(){return reader.size;}public SeekableByteChannel truncate(long n){throw new UnsupportedOperationException();}public boolean isOpen(){return true;}public void close(){}};try(SeekableZip zip=new SeekableZip(channel)){require(zip.getEntry("manifest.json")!=null,"encrypted index");try(InputStream in=zip.getInputStream(zip.getEntry("manifest.json"))){require(in.read()=='m',"encrypted seek");}}}
 System.out.println("PASS handle-only ZIP reads, stored/deflated UTF-8/newline entries, comments, forced ZIP64 index, malformed/truncated records and encrypted seekable channel");}
}
